import { tags } from "typia";

/**
 * Filter options for constraining review analytics by rating scores.
 *
 * This helper type is used by review analytics request DTOs to restrict the set
 * of reviews considered based on numeric rating values stored in
 * shopping_mall_reviews.rating.
 *
 * Clients can specify explicit allowed rating values or a minimum and maximum
 * range. When both are supplied, implementations may intersect the conditions
 * or define precedence as part of endpoint documentation.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IReviewRatingFilter = {
  /**
   * Explicit list of rating values that should be included in analytics.
   *
   * Commonly used to focus on positive-only or negative-only segments, for
   * example [4,5] or [1,2].
   */
  allowedRatings?: (number & tags.Type<"int32">)[] | undefined;

  /**
   * Minimum rating value to include in analytics.
   *
   * When provided, only reviews with rating greater than or equal to this
   * value are counted.
   */
  minRating?: (number & tags.Type<"int32">) | null | undefined;

  /**
   * Maximum rating value to include in analytics.
   *
   * When provided, only reviews with rating less than or equal to this value
   * are counted.
   */
  maxRating?: (number & tags.Type<"int32">) | null | undefined;
};
